import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import type { BaseOption } from '../types.js';

@Component({
  selector: 'base-select',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './base-select.component.html',
  styleUrl: './base-select.component.scss'
})
export class BaseSelect {
  @Input() label = '';
  @Input() id = 'base-select';
  @Input() value = '';
  @Input() options: BaseOption[] = [];
  @Input() disabled = false;
  @Input() required = false;
  @Input() state: 'default' | 'success' | 'error' | 'warning' = 'default';
  @Input() helperText = '';
  @Output() baseChange = new EventEmitter<string>();
}
