import{ChangeDetectionStrategy,Component,Input,HostListener,ElementRef}from'@angular/core';@Component({selector:'base-dropdown',standalone:true,changeDetection:ChangeDetectionStrategy.OnPush,templateUrl:'./base-dropdown.component.html',styleUrl:'./base-dropdown.component.scss'})export class BaseDropdown{constructor(private elementRef:ElementRef){}@Input()label='Opções';open=false;toggle():void{this.open=!this.open;}@HostListener('document:click',['$event'])onClick(event:MouseEvent){if(!this.elementRef.nativeElement.contains(event.target)){this.open=false;}}@HostListener('document:keydown.escape')onEscape(){this.open=false;}}
